<script>
(function () {
    function initConfirmedRescheduleEditor() {
        var form = document.querySelector('.co-page .js-activity-form'), status = form ? form.querySelector('.js-agenda-status') : null;
        if (!form || form.getAttribute('data-confirmed') !== '1' || !status) return;
        var rescheduleFlag = document.createElement('input');
        rescheduleFlag.type = 'hidden'; rescheduleFlag.name = 'reagendar_confirmado'; rescheduleFlag.value = '1';
        form.appendChild(rescheduleFlag);
        function sync() {
            var enabled = String(status.value) === '2';
            rescheduleFlag.disabled = !enabled;
            form.querySelectorAll('.js-reagendar-field').forEach(function (field) {
                if (!enabled && field.hasAttribute('data-confirmed-value')) field.value = field.getAttribute('data-confirmed-value');
                if (field.tagName === 'SELECT') field.disabled = !enabled;
                else field.readOnly = !enabled;
            });
            form.querySelectorAll('.js-confirmed-lock-value').forEach(function (hidden) {
                var name = hidden.getAttribute('data-confirmed-field');
                if (['id_sala', 'id_doctor2', 'id_doctor3'].indexOf(name) !== -1) hidden.disabled = enabled && !!form.querySelector('.js-reagendar-field[name="' + name + '"]');
            });
            form.querySelectorAll('.js-reagendar-availability').forEach(function (box) { box.classList.toggle('is-agenda-hidden', !enabled); });
            if (enabled) {
                var refresh = form.querySelector('.js-refresh-availability');
                if (refresh) refresh.click();
            }
        }
        status.addEventListener('change', sync);
        if (window.jQuery) {
            window.jQuery(status)
                .off('change.confirmedReagendaEditor select2:select.confirmedReagendaEditor')
                .on('change.confirmedReagendaEditor select2:select.confirmedReagendaEditor', sync);
        }
        sync();
    }
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', initConfirmedRescheduleEditor);
    else initConfirmedRescheduleEditor();
})();
</script>
